/**
 * Safety rails for the test harnesses, which create and DROP databases as a superuser.
 * They refuse to run against anything but a disposable server on loopback, and refuse to
 * drop any database whose name was not generated by the harness itself.
 *
 * TEST_DB_ALLOWED_PORT must be set explicitly to the disposable server's port (no default).
 */

const LOOPBACK = new Set(['127.0.0.1', 'localhost', '[::1]', '::1']);
export const GENERATED_DB_RE = /^ops_(?:test|e2e)_[a-z0-9]+_\d+$/;

export function assertDisposableServer(url: string): void {
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    throw new Error('TEST_DATABASE_URL is not a valid URL');
  }
  const allowedPort = process.env.TEST_DB_ALLOWED_PORT;
  if (!allowedPort) throw new Error('test DB guard: set TEST_DB_ALLOWED_PORT to the disposable server port');
  if (!['postgres:', 'postgresql:'].includes(u.protocol)) throw new Error('test DB guard: postgres URL required');
  if (!LOOPBACK.has(u.hostname)) throw new Error(`test DB guard: host must be loopback, got ${u.hostname}`);
  if (u.port !== allowedPort) throw new Error(`test DB guard: port must be ${allowedPort}, got ${u.port || '(default)'}`);
  if (u.searchParams.has('host')) throw new Error('test DB guard: socket/host overrides are not allowed');
}

export function assertGeneratedDatabase(name: string): void {
  if (!GENERATED_DB_RE.test(name)) throw new Error(`test DB guard: refusing to touch non-generated database ${name}`);
}
